from pathlib import Path
p=Path('/mnt/data/hyperfix/index.html');s=p.read_text()
s=s.replace(".nav{max-width:1050px;margin:auto;padding:14px 18px;display:flex;align-items:center;gap:10px}",".nav{max-width:1050px;margin:auto;padding:14px 18px;display:flex;align-items:center;gap:10px;overflow-x:auto;overflow-y:hidden;white-space:nowrap;overscroll-behavior-x:contain;touch-action:pan-x;scrollbar-width:thin}.nav>*{flex:0 0 auto}.top{overflow:hidden}")
s=s.replace(".main{min-width:0}",".main{min-width:0;display:flex;flex-direction:column}.main>#feed,.main>.feedlist{display:flex;flex-direction:column;gap:0;min-width:0}.post{width:100%;min-width:0}.postmedia{display:block;max-height:75vh;object-fit:contain}.shorts{max-width:560px;margin:auto;display:flex;flex-direction:column;gap:16px}.shortvideo{width:100%;height:min(75vh,760px);object-fit:contain;background:#050509;border-radius:16px}")
s=s.replace(".storymedia{display:block;width:100%;max-height:240px;object-fit:contain;border-radius:12px;margin-top:8px}",".storymedia{display:block;width:100%;max-height:240px;object-fit:contain;border-radius:12px;margin-top:8px}.storyactions{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.storyactions button{padding:6px 8px;font-size:12px}.upload-progress{height:7px;background:#333;border-radius:9px;overflow:hidden;margin:10px 0}.upload-progress>i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--pink),var(--purple))}")
# make media uploads robust client accept
s=s.replace('accept="image/*,video/mp4,video/webm,video/quicktime"','accept="image/*,video/*,.mp4,.m4v,.mov,.webm,.3gp,.mkv"')
# story cards actions
old="${s.file?(s.mime&&s.mime.startsWith('video/')?`<video class=\"storymedia\" controls playsinline src=\"${esc(s.file)}\"></video>`:`<img class=\"storymedia\" src=\"${esc(s.file)}\">`):''}<div class=\"small\">${esc(s.body||'')}</div></div>`"
new="${s.file?(s.mime&&s.mime.startsWith('video/')?`<video class=\"storymedia\" controls playsinline preload=\"metadata\" src=\"${esc(s.file)}\"></video>`:`<img class=\"storymedia\" loading=\"lazy\" src=\"${esc(s.file)}\">`):''}<div class=\"small\">${esc(s.body||'')}</div><div class=\"storyactions\"><button onclick=\"storyLike('${s.id}')\">♥ Like</button><button onclick=\"storyComments('${s.id}')\">Comment</button><button onclick=\"shareItem('${s.file||location.href}','HYPER Story')\">Share</button><button onclick=\"storySave('${s.id}')\">Save</button></div><div id=\"story-comments-${s.id}\"></div></div>`"
s=s.replace(old,new)
# postHtml function replace full line
start=s.index('function postHtml(p){');end=s.index('\nasync function likePost',start)
post="""function postHtml(p){let media=p.file?((p.type==='video'||p.type==='short')?`<video class=\"postmedia\" controls playsinline preload=\"metadata\" src=\"${esc(p.file)}\"></video>`:`<img class=\"postmedia\" loading=\"lazy\" src=\"${esc(p.file)}\">`):'';return `<article class=\"post\"><div class=\"posthead\">${avatar(p.user)}<div><b>${esc(p.user?.name)}</b><div class=\"small muted\">${new Date(p.createdAt).toLocaleString()}</div></div><span class=\"tag right\">${p.type==='video'?'VIDEO':p.type.toUpperCase()}</span></div>${media}<p>${esc(p.caption)}</p><div class=\"actions\"><button class=\"ghost\" onclick=\"likePost('${p.id}')\">${p.liked?'♥':'♡'} ${p.likes}</button><button class=\"ghost\" onclick=\"comments('${p.id}')\">Comment ${p.comments}</button><button class=\"ghost\" onclick=\"shareItem(location.origin+'${esc(p.file||'/')}','HYPER Post')\">Share</button><button class=\"ghost\" onclick=\"savePost('${p.id}')\">${p.saved?'Saved ✓':'Save'}</button>${me&&p.userId!==me.id?`<button class=\"ghost\" onclick=\"startChat('${p.userId}')\">Message</button>`:''}</div><div id=\"comments-${p.id}\"></div></article>`}"""
s=s[:start]+post+s[end:]
# inject utility handlers before requireLogin
needle='function requireLogin(fn)'
extra="""async function savePost(id){if(!me)return openAuth();try{let d=await api('/posts/'+id+'/save',{method:'POST'});toast(d.saved?'Post saved':'Post removed from saved');loadFeed();}catch(e){toast(e.message)}}async function shareItem(url,title){try{let full=url.startsWith('http')?url:location.origin+url;if(navigator.share)await navigator.share({title,text:'Check this out on HYPER',url:full});else{await navigator.clipboard.writeText(full);toast('Link copied')}}catch(e){if(e.name!=='AbortError')toast('Share unavailable')}}async function storyLike(id){if(!me)return openAuth();try{await api('/stories/'+id+'/like',{method:'POST'});toast('Story reaction saved')}catch(e){toast(e.message)}}async function storySave(id){if(!me)return openAuth();try{let d=await api('/stories/'+id+'/save',{method:'POST'});toast(d.saved?'Story saved':'Story removed from saved')}catch(e){toast(e.message)}}async function storyComments(id){let el=$('story-comments-'+id);if(el.dataset.open){el.innerHTML='';el.dataset.open='';return}try{let d=await api('/stories/'+id+'/comments');el.dataset.open='1';el.innerHTML=d.comments.map(c=>`<p class=\"small\"><b>${esc(c.user.name)}</b> ${esc(c.body)}</p>`).join('')+(me?`<div class=\"row\"><input id=\"story-comment-${id}\" class=\"field\" placeholder=\"Comment\"><button onclick=\"sendStoryComment('${id}')\">Send</button></div>`:'<p class=\"small\">Login to comment</p>')}catch(e){toast(e.message)}}async function sendStoryComment(id){try{await api('/stories/'+id+'/comments',{method:'POST',body:JSON.stringify({body:$('story-comment-'+id).value})});let el=$('story-comments-'+id);el.dataset.open='';await storyComments(id)}catch(e){toast(e.message)}}
"""
s=s.replace(needle,extra+needle)
# improve upload UI, file validation, button disabled
old="async function createPost(){try{let f=new FormData();f.append('caption',$('caption').value);f.append('kind',$('postKind').value);if($('postFile').files[0])f.append('file',$('postFile').files[0]);await api('/posts',{method:'POST',body:f});toast('Upload successful');home()}catch(e){toast(e.message)}}"
new="async function createPost(){let file=$('postFile').files[0],btn=document.querySelector('#main button[onclick=\"createPost()\"]');if(file&&file.size>100*1024*1024)return toast('File must be 100 MB or smaller');if(file&&!(/^(image|video)\\//i.test(file.type)||/\\.(jpe?g|png|gif|webp|avif|mp4|m4v|mov|webm|3gp|mkv)$/i.test(file.name)))return toast('Choose a photo or video file');try{btn.disabled=true;btn.textContent='Uploading…';let f=new FormData();f.append('caption',$('caption').value);f.append('kind',$('postKind').value);if(file)f.append('file',file);await api('/posts',{method:'POST',body:f});toast('Upload successful');home()}catch(e){toast('Upload failed: '+e.message)}finally{if(btn){btn.disabled=false;btn.textContent='Share'}}}"
s=s.replace(old,new)
# short feed actions
s=s.replace("<button class=\"ghost\" onclick=\"comments('${p.id}')\">Comments</button></div>","<button class=\"ghost\" onclick=\"comments('${p.id}')\">Comment ${p.comments}</button><button class=\"ghost\" onclick=\"shareItem(location.origin+'${esc(p.file)}','HYPER Short')\">Share</button><button class=\"ghost\" onclick=\"savePost('${p.id}')\">Save</button></div>")
p.write_text(s)
